"""Reconcile revised proposal text/style with the supplied blue, green, purple references."""
from pathlib import Path
import re
ROOT = Path(__file__).resolve().parent


def swap(path, old, new, required=True):
    text = path.read_text(encoding="utf-8")
    if old not in text:
        if required:
            print("NOT FOUND", path.name, old[:80])
        return
    path.write_text(text.replace(old, new), encoding="utf-8")
    print("Updated", path.name, old[:45])


def replace_section(path, eyebrow, body):
    text = path.read_text(encoding="utf-8")
    pattern = re.compile(r'<section(?:\s+id="[^"]+")?><div class="eyebrow">' + re.escape(eyebrow) + r'</div>.*?</section>')
    id_attr = ' id="applications"' if eyebrow.startswith('06 /') else ' id="governance"' if eyebrow.startswith('07 /') else ''
    replacement = '<section' + id_attr + '><div class="eyebrow">' + eyebrow + '</div>' + body + '</section>'
    updated, count = pattern.subn(replacement, text, count=1)
    if count != 1:
        print("SECTION NOT FOUND", path.name, eyebrow)
    else:
        path.write_text(updated, encoding="utf-8")
        print("Section updated", path.name, eyebrow)


