from bs4 import BeautifulSoup
for file in ROOT.glob('proposal-*.html'):
    soup = BeautifulSoup(file.read_text(encoding='utf-8'), 'html.parser')
    for node in soup(['style', 'script', 'svg']):
        node.decompose()
    visible = soup.get_text(' ', strip=True)
    print('\nLEGACY REVIEW', file.name)
    for term in ['navy', 'gold', 'deep teal', 'terracotta', 'organic', 'forest', 'botanical', 'Rooted in care', 'Barishal Green', 'green campus', 'regional']:
        for match in list(re.finditer(term, visible, re.I))[:3]:
            print(visible[max(0, match.start()-90):match.end()+150])
